}
const intensityColors = ['#ef4444', '#f97316', '#eab308', '#84cc16', '#15803d']

const cantonCounts = computed(() => {
  const counts = new Map(props.stats.regionCounts.map(({ code, count }) => [code, count]))
  return cantonCodes.map((code) => ({ code, count: counts.get(code) ?? 0 }))
})

const maxCantonCount = computed(() => Math.max(0, ...cantonCounts.value.map(({ count }) => count)))

function cantonPath(code) {
  return cantonPaths[code]
}

function cantonColor(count) {
  if (count === 0 || maxCantonCount.value === 0) return '#eeeeee'
  const ratio = count / maxCantonCount.value
  const start = [238, 238, 238]
  const end = [30, 58, 138]
  const channels = start.map((channel, index) => Math.round(channel + (end[index] - channel) * ratio))
  return `rgb(${channels.join(', ')})`
}

function formatAvg(value) {
  if (value === null || value === undefined) return '—'
  return value.toFixed(1)
}

function gaugeStyle(value, index) {
  if (value === null || value === undefined) return { width: '0%' }
  const filled = Math.max(0, Math.min(5, value) - index)
  return {
    width: `${filled * 100}%`,
    backgroundColor: intensityColors[index],
  }
}

function displayGaugeValue(value) {
  return value !== null && value !== undefined
}

function usageGaugeStyle(value) {
  const percentage = Math.max(0, Math.min(100, value ?? 0))
  return { width: `${percentage}%` }
}
</script>

